import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import Header from "./../../components/Header/Header";
import Footer from "./../../components/Footer/Footer";
import "./view-result-page.css"; // Updated CSS

const subjects = ["Computer Networks", "Data Structures", "OS", "OOPs", "DBMS"];

// Dummy performance data for subjects
const generatePerformanceData = () => {
  return subjects.map((subject) => ({
    subject,
    scores: Array.from({ length: 5 }, (_, i) => ({
      test: `Test ${i + 1}`,
      score: Math.random() * 2, // Random score between 0 and 2
    })),
  }));
};

const performanceData = generatePerformanceData();

const ViewResultPage: React.FC = () => {
  const [testId, setTestId] = useState<string>("");
  const [results, setResults] = useState<any[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const navigate = useNavigate();

  const fetchResults = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setResults([]);

    if (!testId.trim()) {
      setMessage("Please enter a valid Test ID.");
      return;
    }

    try {
      const response = await fetch("http://localhost:5000/viewresult", {
        method: "POST", // Change to POST to send testId in body
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ testid: testId }),
      });

      if (response.ok) {
        const data = await response.json();
        setResults(data.result);
        setMessage(null);
      } else {
        const error = await response.json();
        setMessage(`Error: ${error.error || "Failed to fetch results."}`);
      }
    } catch (err) {
      setMessage(`Error: ${err}`);
    }
  };

  const goToHomePage = () => {
    navigate("/");
  };

  return (
    <div className="App">
      <Header />
      <div className="result-container">
        {/* Left Side: Performance Charts */}
        <div className="performance-section">
          <h2>Performance Analysis</h2>
          {performanceData.map((subjectData, index) => (
            <div key={index} className="chart-container">
              <h3>{subjectData.subject}</h3>
              <ResponsiveContainer width="95%" height={150}>
                <LineChart data={subjectData.scores}>
                  <XAxis dataKey="test" />
                  <YAxis domain={[0, 2]} />
                  <Tooltip />
                  <Line type="monotone" dataKey="score" stroke="#8884d8" />
                </LineChart>
              </ResponsiveContainer>
            </div>
          ))}
        </div>

        {/* Right Side: Results Analysis */}
        <div className="result-section">
          <h2>View Results</h2>
          <form onSubmit={fetchResults} className="result-form">
            <div className="form-group">
              <label htmlFor="testId">Test ID</label>
              <input
                type="text"
                id="testId"
                value={testId}
                onChange={(e) => setTestId(e.target.value)}
                placeholder="Enter Test ID"
                required
              />
            </div>
            <button type="submit" className="fetch-button">
              Fetch Results
            </button>
          </form>
          {message && <p className="feedback-message">{message}</p>}

          {results.length > 0 && (
            <div className="results-container">
              <h3>Results</h3>
              <table className="results-table">
                <thead>
                  <tr>
                    <th>Question</th>
                    <th>Your Answer</th>
                    <th>Reference Answer</th>
                  </tr>
                </thead>
                <tbody>
                  {results.map((result, index) => (
                    <tr key={index}>
                      <td>{result.question || "N/A"}</td>
                      <td>{result.answer || "N/A"}</td>
                      <td>{result.reference_answer || "N/A"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          <button className="home-button" onClick={goToHomePage}>
            Go to Home Page
          </button>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewResultPage;
